import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrading.md","filePath":"guide/upgrading.md","lastUpdated":1793807984000}'),n={name:"guide/upgrading.md"};function r(c,e,i,s,h,l){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>chamvi is pre-1.0: a minor release may break the API. Each section lists what changed and the exact replacement.</p><h2 id="upgrading-to-0-7" tabindex="-1">Upgrading to 0.7 <a class="header-anchor" href="#upgrading-to-0-7" aria-label="Permalink to &quot;Upgrading to 0.7&quot;">​</a></h2><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><p><a href="/guide/dispatch#simple-agents">Simple agents</a> (<code>defineSimpleAgent({ run })</code>, no model) and <a href="/guide/dispatch#generated-dispatch-tools">generated dispatch tools</a> arrived (<a href="https://github.com/chamvi/chamvi/issues/131" target="_blank" rel="noreferrer">#131</a>).</p><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.6)</th><th>Replacement (0.7)</th></tr></thead><tbody><tr><td><code>defineAgent()</code></td><td>Builds every agent</td><td>Removed: <code>defineModelAgent()</code> takes the same input and runs the same checks (rename the call). A definition with <code>run</code> is refused there: build it with <code>defineSimpleAgent()</code></td></tr><tr><td><code>Agent</code></td><td><code>{ name, definition }</code></td><td>A union of <code>ModelAgent</code> and <code>SimpleAgent</code>, told apart by <code>agent.kind</code> (<code>&#39;model&#39;</code> or <code>&#39;simple&#39;</code>), which narrows <code>agent.definition</code> as well. An agent built by hand needs <code>kind</code>: the engine refuses one whose <code>kind</code> is neither or disagrees with its definition. A folder or package agent built by an older core (no <code>kind</code>) loads as a model agent</td></tr><tr><td><code>AgentDefinition</code></td><td>One shape, <code>instructions</code> required</td><td>A union of <code>ModelAgentDefinition</code> and <code>SimpleAgentDefinition</code>: on the union, <code>agent.definition.instructions</code>, <code>model</code>, <code>output</code>, <code>conversation</code> and <code>skills</code> read as possibly <code>undefined</code>, <code>run</code> and <code>description</code> are new. Check <code>agent.kind === &#39;model&#39;</code> before reading the model fields</td></tr><tr><td>Hand-written dispatch tools</td><td>A <code>defineTool()</code> around <code>dispatch()</code> that only forwarded the call</td><td>Still works; <code>dispatchTools({ roles })</code> generates the same tool from the role, with <code>agent.on({ idempotencyKey, concurrencyKey, address, description })</code> deciding what the tool did. The hooks see only the payload: keep the hand-written tool when it derives a key or the address from anything else (the trigger&#39;s <code>receivedAt</code>, the run), or put that value into the payload</td></tr></tbody></table><h2 id="upgrading-to-0-6" tabindex="-1">Upgrading to 0.6 <a class="header-anchor" href="#upgrading-to-0-6" aria-label="Permalink to &quot;Upgrading to 0.6&quot;">​</a></h2><h3 id="breaking-changes-1" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-1" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><p>Hand-offs became <a href="/guide/dispatch">dispatch</a>: a tool starts runs of its own or another agent and may wait for them (<a href="https://github.com/chamvi/chamvi/issues/129" target="_blank" rel="noreferrer">#129</a>, <a href="https://github.com/chamvi/chamvi/issues/76" target="_blank" rel="noreferrer">#76</a>). No alias is left for the hand-off names.</p><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.5)</th><th>Replacement (0.6)</th></tr></thead><tbody><tr><td>Subscription</td><td><code>handoff.on(opts?)</code>, at most one per agent, subscription id <code>handoff</code></td><td><code>agent.on(opts?)</code>, one per role; the role is the subscription id, default <code>&#39;default&#39;</code> (<code>DEFAULT_DISPATCH_ROLE</code>). <code>agent.on({ role: &#39;handoff&#39; })</code> keeps the old id (stored runs carry it as <code>trigger.trigger</code>)</td></tr><tr><td>Starting a run</td><td><code>startHandoff(ctx, input)</code></td><td><code>dispatch(ctx, input)</code>; <code>input.role</code> picks the role. <code>dispatchTo(ctx, { agent, ... })</code> reaches another agent</td></tr><tr><td>Types</td><td><code>HandoffInput</code>, <code>HandoffResult</code>, <code>HandoffSubscriber</code>, <code>HandoffSubscriptionOptions</code></td><td><code>DispatchInput</code>, <code>DispatchResult</code>, <code>AgentSubscriber</code>, <code>AgentSubscriptionOptions</code></td></tr><tr><td>Constants</td><td><code>HANDOFF_SUBSCRIPTION_ID</code>, <code>MAX_HANDOFF_DEPTH</code> (1), <code>DEFAULT_MAX_HANDOFFS_PER_RUN</code> (100)</td><td><code>DEFAULT_DISPATCH_ROLE</code>, <code>DEFAULT_DISPATCH_MAX_DEPTH</code> (1, per role through <code>agent.on({ maxDepth })</code>, at most <code>DISPATCH_DEPTH_MAX</code> 8), <code>DEFAULT_MAX_DISPATCHES_PER_RUN</code> (100)</td></tr><tr><td>Per-run limit</td><td><code>maxPerRun</code> counted every hand-off of the run (<code>handoff-count:&lt;runId&gt;</code>)</td><td>Counted per target agent and role (<code>dispatch-count:&lt;runId&gt;:&lt;agent&gt;:&lt;role&gt;</code>)</td></tr><tr><td>Keys</td><td>Effect <code>&lt;runId&gt;:handoff:&lt;hash&gt;</code>, idempotency claim <code>handoff:&lt;key&gt;</code></td><td><code>&lt;runId&gt;:dispatch:&lt;hash&gt;</code> (the hash also covers the agent and the role), <code>dispatch:&lt;role&gt;:&lt;key&gt;</code></td></tr><tr><td>Lineage</td><td><code>trigger.parent: { kind: &#39;handoff&#39;, runId, agent, depth }</code></td><td><code>{ kind: &#39;dispatch&#39;, runId, agent, role, depth }</code>, plus <code>run.parentRunId</code> and <code>run.subtreeUsage</code>. The migration rewrites stored hand-off parents to role <code>handoff</code></td></tr><tr><td>Wait point</td><td><code>run.waiting</code> (<code>WaitPoint</code>) was always an approval</td><td>A union on <code>kind</code>: <code>ApprovalWaitPoint</code> (<code>kind: &#39;approval&#39;</code>, plus the generic <code>id</code>, equal to <code>approvalId</code>) or <code>DispatchWaitPoint</code> (<code>kind: &#39;dispatch&#39;</code>, <code>runIds</code>). Narrow on <code>kind === &#39;approval&#39;</code> before reading <code>title</code>, <code>approvalId</code> or <code>options</code></td></tr><tr><td>MCP <code>run_&lt;agent&gt;</code> result</td><td><code>waiting: { toolName, title, ... }</code></td><td><code>waiting.kind</code> <code>&#39;approval&#39;</code> (with <code>runId</code> and <code>agent</code>: the run to answer, possibly a descendant) or <code>&#39;dispatch&#39;</code> (<code>get_run</code> only)</td></tr><tr><td>Custom repositories</td><td></td><td><code>Run.parentRunId</code> (set by <code>insert</code> from <code>trigger.parent.runId</code>, a missing parent throws <code>RunNotFoundError</code>), <code>Run.subtreeUsage</code>, <code>RunFindOptions.ids</code>, <code>parentRunId</code>, <code>parentRunIds</code>, <code>hasParent</code> and <code>waitKind</code>, <code>RunUpdateOptions.expectWaitId</code> and <code>keepUpdatedAt</code>, both wait point kinds read back through <code>normalizeWaitPoint()</code>. <code>describeRepositoryContract()</code> checks each (<a href="/repositories/writing-a-repository#lineage-and-wait-points">Lineage and wait points</a>)</td></tr></tbody></table><p>Drain hand-off trees before upgrading: a parent that replays a <code>startHandoff()</code> call under the new effect keys can start a second child, and a stored child of subscription id <code>handoff</code> matches no role unless the agent declares <code>agent.on({ role: &#39;handoff&#39; })</code>.</p><h3 id="database-migration" tabindex="-1">Database migration <a class="header-anchor" href="#database-migration" aria-label="Permalink to &quot;Database migration&quot;">​</a></h3><p>0.6 ships <code>1792800000000-run-lineage.ts</code> (<code>RunLineage1792800000000</code>): <code>chamvi_runs.parent_run_id</code> (indexed, a self foreign key, <code>NOT VALID</code> so legacy children of a deleted parent stay) and <code>subtree_usage</code>, the <code>parent_run_id</code> backfill from <code>trigger.parent.runId</code>, the hand-off parent rewrite, and the generic <code>id</code> on every pending approval wait point, so an approval that waits across the upgrade can still be answered. See <a href="/repositories/database#migrations">Migrations</a>.</p><h2 id="upgrading-to-0-5" tabindex="-1">Upgrading to 0.5 <a class="header-anchor" href="#upgrading-to-0-5" aria-label="Permalink to &quot;Upgrading to 0.5&quot;">​</a></h2><h3 id="breaking-changes-2" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-2" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.4)</th><th>Replacement (0.5)</th></tr></thead><tbody><tr><td>Node</td><td><code>&gt;=24.3.0</code></td><td><code>&gt;=26.0.0</code></td></tr><tr><td>Base image</td><td><code>ghcr.io/chamvi/node:24</code></td><td><code>ghcr.io/chamvi/node:26</code>; build stages move to <code>node:26-trixie-slim</code>. The <code>24</code> tag stops receiving rebuilds</td></tr><tr><td><code>chamvi build</code> target</td><td><code>node24</code></td><td><code>node26</code></td></tr><tr><td>Sandbox image <code>ghcr.io/chamvi/sandbox-node:24</code></td><td>Rebuilt as a deprecated workspace image</td><td>Not built anymore; use the default <code>ghcr.io/chamvi/sandbox-dev</code> (<code>mise use -g node@26</code>) or your own image</td></tr></tbody></table><h2 id="upgrading-to-0-4" tabindex="-1">Upgrading to 0.4 <a class="header-anchor" href="#upgrading-to-0-4" aria-label="Permalink to &quot;Upgrading to 0.4&quot;">​</a></h2><h3 id="breaking-changes-3" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-3" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.3)</th><th>Replacement (0.4)</th></tr></thead><tbody><tr><td>Store package renamed</td><td><code>@chamvi/store-typeorm</code></td><td><code>@chamvi/store-db</code>; replace the dependency and every import. Tables and migration history keep their names</td></tr><tr><td>Store aggregate</td><td><code>new MemoryStore(options)</code>, <code>new TypeormStore(options)</code>, facade methods such as <code>engine.store.getRun(id)</code></td><td><code>createMemoryStore(options)</code>, <code>createDatabaseStore(options)</code>, role methods such as <code>engine.store.runs.findOne(id)</code>; every method is mapped on <a href="/repositories/#updating-existing-callers">Stores and repositories</a></td></tr><tr><td>Repository interfaces</td><td><code>IRunStore</code>, <code>IStepStore</code>, <code>ICheckpointStore</code>, <code>IIdempotencyStore</code>, <code>ILockStore</code>, <code>IEffectStore</code>, <code>IStateStore</code>, <code>IArtifactStore</code>, <code>IAgentRevisionStore</code>; <code>IStore</code> extended them</td><td><code>IRunRepository</code>, <code>IStepRepository</code>, <code>ICheckpointRepository</code>, <code>IIdempotencyRepository</code>, <code>ILockRepository</code>, <code>IEffectRepository</code>, <code>IStateRepository</code>, <code>IArtifactRepository</code>, <code>IAgentRevisionRepository</code>; <code>IStore</code> holds one of each (<code>store.runs</code>, <code>store.steps</code>, ...)</td></tr><tr><td>Database store options</td><td><code>TypeormStoreOptions</code></td><td><code>DatabaseStoreOptions</code>; <code>createDatabaseStore()</code> returns <code>DatabaseStore</code></td></tr><tr><td>Purging expired rows</td><td><code>store.purgeExpired(now?)</code> resolving <code>PurgeResult</code></td><td><code>store.idempotency.purgeExpired(now?)</code> and <code>store.locks.purgeExpired(now?)</code>, each resolving the number of deleted rows (<code>@chamvi/app</code> schedules both)</td></tr><tr><td>Agent instructions</td><td><code>AgentDefinition.instructions: string</code></td><td><code>instructions: AgentInstructions</code> (a string or an array of system, user and assistant messages). A string still works; code that reads <code>agent.definition.instructions</code> as a string must handle the array form</td></tr><tr><td>Channel context</td><td><code>ChannelContext.engine: Engine</code>; no conversation intake</td><td><code>ChannelContext.engine: IEngine</code> (type against the interface, not the class); <code>ChannelContext.dispatchConversation(envelope, target)</code> is required: a hand-built context needs one, get both from <code>engine.channelContext(channel)</code></td></tr><tr><td>Engine typing in apps</td><td><code>AppTokens.ENGINE: Engine</code>, <code>ILifecycleHook.engineCreated(engine: Engine)</code></td><td>Both typed <code>IEngine</code>. Cast to <code>Engine</code> only where you need a member outside <code>IEngine</code></td></tr><tr><td><code>Engine.stop()</code></td><td>Stopped polling and the channels</td><td>Also halts the queue and waits for an in-flight <code>start()</code> and <code>prepare()</code> (skill preparation). A skill provider that ignores cancellation holds <code>stop()</code> until it settles</td></tr><tr><td>Cron schedule lock</td><td><code>createStoreScheduleLock(store, owner)</code></td><td><code>createRepositoryScheduleLock(store.locks, owner)</code> (<code>@chamvi/channel-cron</code>, takes an <code>ILockRepository</code>)</td></tr><tr><td>Engine concurrency option</td><td><code>new Engine({ maxConcurrentRuns })</code></td><td><code>new Engine({ concurrencyMaxRuns })</code>; the variable <code>CHAMVI_MAX_CONCURRENT_RUNS</code> is unchanged</td></tr><tr><td>App config concurrency</td><td><code>readConfig(env).engine.maxConcurrentRuns</code></td><td><code>readConfig(env).engine.concurrencyMaxRuns</code> (<code>AppConfig</code>); the variable <code>CHAMVI_MAX_CONCURRENT_RUNS</code> is unchanged</td></tr><tr><td>Run references (memory, database and custom stores)</td><td><code>steps.insert</code>, <code>checkpoints.save</code> and <code>conversations.beginTurn</code> accepted any run id on the memory store; Postgres failed with a raw foreign key error</td><td>All three throw <code>RunNotFoundError</code> for a run the store does not hold and write nothing, on memory and Postgres alike. <code>describeRepositoryContract()</code> checks it, so a custom store must implement it to pass (<a href="/repositories/writing-a-repository#run-references">Run references</a>). Insert the run first; a test that spreads <code>{ ...createMemoryStore(), runs: custom }</code> builds <code>steps</code>/<code>checkpoints</code>/<code>conversations</code> with <code>hasRun</code> over <code>custom</code> (see <a href="/repositories/memory">Memory repositories</a>)</td></tr><tr><td>Node</td><td><code>&gt;=22</code></td><td><code>&gt;=24.3.0</code></td></tr><tr><td>Git credential mode (<code>@chamvi/sandbox</code>)</td><td><code>credentialMode</code> (<code>CredentialMode</code>) and <code>CHAMVI_GIT_CREDENTIAL_MODE</code> chose tools-only or workspace-installed credentials</td><td>Removed; a set variable or option is refused with <code>InvalidAgentDefinitionError</code> naming them: unset the variable and drop the option. Workspace-installed credentials are the only mode; <code>PushPolicy</code> binds <code>git_push</code> only, so restrict writes through token scope and branch protection</td></tr><tr><td>Image requirements (<code>@chamvi/sandbox</code>)</td><td><code>IMAGE_REQUIREMENTS</code> <code>[&#39;sh&#39;, &#39;git&#39;, &#39;timeout&#39;]</code></td><td><code>[&#39;sh&#39;, &#39;git&#39;, &#39;timeout&#39;, &#39;head&#39;, &#39;base64&#39;, &#39;tr&#39;]</code>: the image probe also refuses an image without <code>/bin/sh</code> or without <code>head</code>, <code>base64</code> and <code>tr</code> in <code>/usr/bin</code> or <code>/bin</code> (coreutils or busybox provide them; <code>ghcr.io/chamvi/sandbox-dev</code> has them)</td></tr><tr><td><code>write_file</code> over a file holding an issued token</td><td>Wrote a literal <code>[redacted]</code> over the token</td><td>Each <code>[redacted]</code> the model read is restored in order; content whose markers do not line up, or with <code>[redacted]</code> over an existing file that cannot be read as text, is refused (<code>ValidationError</code>) and nothing is written</td></tr><tr><td>Event-started runs (<code>github</code>, <code>webhook</code>)</td><td>A delivery started a run whose write tools ran at once, so an event-driven auto-merge or auto-reply flow acted without a human</td><td>The <code>github</code> and <code>webhook</code> channels are untrusted ingress: their runs are tainted from the first step, and <code>github_merge_pull_request</code>, <code>github_create_pull_request</code>, <code>github_create_issue</code>, <code>github_propose_change</code>, <code>git_push</code> and a <code>github_create_comment</code> on another issue than the source one wait for an approval (the source issue gets a generic &quot;An outbound operation requires review&quot; comment, never the arguments). Answer it in the approval inbox or through <code>POST /runs/:id/approve</code> (MCP <code>approve_run</code>). An agent whose own policy already decides opts out per tool: <code>trust: { tools: { github_merge_pull_request: { guardWhenTainted: false } } }</code> (<a href="/deployment/github-app#approvals-in-event-started-runs">Approvals in event-started runs</a>)</td></tr><tr><td>Run taint</td><td>No taint column</td><td>Database migration <code>ConversationsRunTaint1792713600000</code> adds <code>chamvi_runs.taint</code> and backfills unfinished runs; it needs downtime (below). Custom stores must persist <code>Run.taint</code> (<a href="/repositories/writing-a-repository#persist-run-taint">Persist run taint</a>)</td></tr></tbody></table><h3 id="new-in-0-4" tabindex="-1">New in 0.4 <a class="header-anchor" href="#new-in-0-4" aria-label="Permalink to &quot;New in 0.4&quot;">​</a></h3><p>Run taint, the outbound gates and repository guidance are new, so 0.3 apps have nothing to migrate beyond the rows above. In their final 0.4 form:</p><ul><li>The coding read and shell tools (<code>read_file</code>, <code>grep</code>, <code>glob</code>, <code>list_files</code>, <code>git_diff</code>, <code>bash</code>, <code>bash_output</code>) taint the run in every workspace, repo-less ones included; opt a tool out with <code>trust.tools: { bash: { taint: false } }</code> only where its output is trusted.</li><li><code>git_push</code> with <code>push: { mode: &#39;approve&#39; }</code> asks once in a tainted run: the outbound gate&#39;s private approval carries the push title and commit log (<code>ToolTrust.approvalDetail</code>, <code>outboundApproved(ctx)</code>) and is answered in the approval inbox or API; <code>push.channel</code> is not asked then. A push the policy refuses is denied before the gate asks.</li><li>A failing repository guidance collection gives <code>instructions: null</code> plus <code>instructionsError</code> in <code>create_workspace</code> and <code>read_file</code>; <code>read_file</code> in a repo-less workspace omits <code>instructions</code>.</li><li><code>ghcr.io/chamvi/sandbox-dev</code> ships the GitHub CLI (<code>gh</code>, the current release at build time); pin the image digest for a fixed version.</li></ul><p>Conversation memory is opt-in and new, so 0.3 apps have nothing to migrate: storage is <code>store.conversations</code> (both built-in stores carry it), policy is <code>createApp({ conversations: { authorize } })</code> or <code>EngineOptions.conversations</code>. See <a href="/guide/conversations">Conversations</a> for the setup.</p><h3 id="database-migration-1" tabindex="-1">Database migration <a class="header-anchor" href="#database-migration-1" aria-label="Permalink to &quot;Database migration&quot;">​</a></h3><p>0.4 ships one new migration, <code>1792713600000-conversations-run-taint.ts</code> (<code>ConversationsRunTaint1792713600000</code>): the conversation tables, the run and checkpoint conversation bindings, the foreign keys (the two on legacy steps and checkpoints <code>NOT VALID</code>, see <a href="/repositories/database#validating-the-legacy-constraints">Validating the legacy constraints</a>), indexes on the new foreign key columns, <code>chamvi_runs.taint</code> and the backfill that taints every <code>queued</code>, <code>running</code>, <code>waiting</code> and <code>interrupted</code> run with <code>{ at: &lt;migration time&gt;, source: &#39;migration:legacy-run&#39; }</code>.</p><div class="warning custom-block"><p class="custom-block-title">Development databases</p><p>A database that ran a pre-release build of this branch recorded <code>Conversations1792713600000</code> (and maybe <code>RunTaint1792800000000</code>). Migrating it fails with &quot;relation already exists&quot;. Recreate the disposable database; never reset a production one for this.</p></div><h3 id="upgrade-procedure-downtime" tabindex="-1">Upgrade procedure (downtime) <a class="header-anchor" href="#upgrade-procedure-downtime" aria-label="Permalink to &quot;Upgrade procedure (downtime)&quot;">​</a></h3><p>Old and new runtimes must never share the store, not even during a rolling update. An old approval poller can post a tainted run&#39;s private approval body to its source channel, and an old worker or job can create or checkpoint untainted runs after the one-time backfill. Claims and locks do not prevent this.</p><ol><li><strong>Suspend the run-job CronJobs</strong> (<code>kubectl patch cronjob &lt;name&gt; -p &#39;{&quot;spec&quot;:{&quot;suspend&quot;:true}}&#39;</code>, or <code>suspend: true</code> on each <code>cronJobs[]</code> entry of the <code>agent-app</code> chart) and wait for running job pods to finish. A <code>Recreate</code> Deployment does not cover CronJobs, and <code>CHAMVI_MIGRATE</code> defaults to <code>true</code> in job mode too: a 0.3 job pod started during the upgrade writes runs the backfill never sees.</li><li><strong>Stop every old process</strong>: scale the Deployment to 0 (ingress, workers, approval pollers) and wait for the pods to exit. Draining executions alone is not enough.</li><li><strong>Migrate in a maintenance window</strong>: run <code>chamvi migrate</code> once with the new image (<code>DATABASE_URL</code> set). Alternatively start the new Deployment with the default <code>CHAMVI_MIGRATE=true</code>; with <code>CHAMVI_MIGRATE=false</code> everywhere, <code>chamvi start --check</code> refuses the unmigrated database.</li><li><strong>Start only 0.4 binaries</strong>: scale the Deployment up, then resume the CronJobs with the new image. Resumed legacy runs are tainted, so their guarded tools ask for approval.</li></ol><p>See <a href="/deployment/replicas#upgrading-to-untrusted-content-gates">Multiple replicas</a> for why each step matters.</p><h3 id="release-time-owner-actions" tabindex="-1">Release-time owner actions <a class="header-anchor" href="#release-time-owner-actions" aria-label="Permalink to &quot;Release-time owner actions&quot;">​</a></h3><p>These are not code changes; the maintainer does them when 0.4.0 is published:</p><ul><li>After the first <code>@chamvi/store-db</code> publish: <code>npm deprecate @chamvi/store-typeorm &quot;renamed to @chamvi/store-db&quot;</code>.</li><li>Check that the <code>NPM_TOKEN</code> used by <code>release.yml</code> (monoship) may create new packages: <code>@chamvi/skills</code> and <code>@chamvi/store-db</code> publish for the first time.</li><li><code>@chamvi/skills</code> depends on a Git URL (<code>git+https://github.com/tada5hi/skills-cli.git#&lt;sha&gt;</code>): registry-only proxies and the agent-template lockfile check refuse it. Publish or vendor the fork before relying on it (<a href="https://github.com/chamvi/chamvi/issues/97" target="_blank" rel="noreferrer">#97</a>).</li><li>Downstream: bump <a href="https://github.com/chamvi/helm" target="_blank" rel="noreferrer">chamvi/helm</a> and <a href="https://github.com/chamvi/agent-template" target="_blank" rel="noreferrer">chamvi/agent-template</a> from <code>^0.3.x</code> to <code>^0.4.0</code> after publishing (Node 24, the CronJob suspend note in the chart README, no <code>CHAMVI_GIT_CREDENTIAL_MODE</code>).</li></ul>',33)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
